import sqlite3,pathlib
p=pathlib.Path('/var/lib/entityos/data/unified.db'); c=sqlite3.connect('file:'+str(p)+'?mode=ro',uri=True)
for t in ['durable_memory','turns','memory_tabelle','f2_konversation']:
 try:
  cols=[r[1] for r in c.execute(f'pragma table_info({t})')]; print(t,'cols',cols)
  scope=next((x for x in ['user_id','person_id','speaker_id','owner'] if x in cols),None)
  if scope: print(t,'scope_counts',c.execute(f"select coalesce({scope},'<null>'),count(*) from {t} group by {scope} order by count(*) desc limit 12").fetchall())
  else: print(t,'scope_counts','NO_SCOPE')
 except Exception as e: print(t,'ERR',e)
c.close()
PY
